// CrudScreen — generated by `mcn build --target flutter` for `crud_table`.
// List / search / filter / create / edit / delete / approve for one Resource.
import 'dart:async';
import 'dart:convert';

import 'package:file_picker/file_picker.dart';
import 'package:flutter/material.dart';
import 'package:url_launcher/url_launcher.dart';

import 'api.dart';
import 'auth.dart';
import 'models.dart';
import 'widgets.dart';

const _all = '__all__';

class CrudScreen extends StatefulWidget {
  const CrudScreen({super.key, required this.resource, this.columns, this.title});

  final Resource resource;
  final List<String>? columns;
  final String? title;

  @override
  State<CrudScreen> createState() => _CrudScreenState();
}

class _CrudScreenState extends State<CrudScreen> {
  final _rows = <Map<String, dynamic>>[];
  int _total = 0;
  int _page = 1;
  bool _loading = true;
  String _error = '';
  String _search = '';
  String _filter = _all;
  String _approval = _all;
  Timer? _debounce;
  Set<String> _available = {};

  Resource get r => widget.resource;
  Field? get _filterField {
    for (final f in r.fields) {
      if (f.type == 'choice') return f;
    }
    return null;
  }

  bool get _hasApproval => _available.contains(r.endpoints['approve']);

  @override
  void initState() {
    super.initState();
    _discover();
    _load(reset: true);
  }

  @override
  void dispose() {
    _debounce?.cancel();
    super.dispose();
  }

  /// Which optional endpoints (approval) the backend has enabled.
  Future<void> _discover() async {
    try {
      final d = await api.get('/');
      final names = <String>{
        for (final e in (d['endpoints'] as List? ?? const [])) '/${e['name']}',
      };
      if (mounted) setState(() => _available = names);
    } catch (_) {}
  }

  Future<void> _load({bool reset = false}) async {
    if (reset) _page = 1;
    setState(() {
      _loading = true;
      _error = '';
    });
    final query = <String, String>{'page': '$_page'};
    if (_search.isNotEmpty) query['search'] = _search;
    final ff = _filterField;
    if (ff != null && _filter != _all) query[ff.name] = _filter;
    if (_approval != _all) query['approval_status'] = _approval;
    try {
      final d = await api.get(r.endpoints['list']!, query);
      final items = [for (final i in (d['items'] as List? ?? const [])) Map<String, dynamic>.from(i as Map)];
      setState(() {
        if (reset) _rows.clear();
        _rows.addAll(items);
        _total = (d['total'] as num?)?.toInt() ?? _rows.length;
      });
    } catch (e) {
      setState(() => _error = e.toString());
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  void _onSearch(String text) {
    _debounce?.cancel();
    _debounce = Timer(const Duration(milliseconds: 350), () {
      _search = text.trim();
      _load(reset: true);
    });
  }

  bool _canRead(AuthState auth, Field f) =>
      f.readRoles.isEmpty || !auth.enabled || f.readRoles.contains(auth.role);

  Future<void> _open([Map<String, dynamic>? row]) async {
    final changed = await Navigator.of(context).push<bool>(MaterialPageRoute(
      builder: (_) => RecordScreen(resource: r, row: row, approval: _hasApproval),
    ));
    if (changed == true) _load(reset: true);
  }

  @override
  Widget build(BuildContext context) {
    final auth = AuthScope.of(context);
    final canCreate = auth.can(r.endpoints['create']!);
    final shown = (widget.columns == null || widget.columns!.isEmpty)
        ? r.fields.where((f) => f.type != 'password').take(5).toList()
        : [for (final c in widget.columns!) ...r.fields.where((f) => f.name == c)];
    final visible = shown.where((f) => _canRead(auth, f)).toList();
    final ff = _filterField;
    final titleField = r.labelField;

    return Scaffold(
      floatingActionButton: canCreate
          ? FloatingActionButton.extended(
              onPressed: () => _open(),
              icon: const Icon(Icons.add),
              label: Text('Add ${r.label.toLowerCase()}'),
            )
          : null,
      body: Column(children: [
        Padding(
          padding: const EdgeInsets.fromLTRB(16, 12, 16, 4),
          child: Row(children: [
            Expanded(
              child: TextField(
                onChanged: _onSearch,
                decoration: InputDecoration(
                  hintText: 'Search ${r.plural.toLowerCase()}…',
                  prefixIcon: const Icon(Icons.search),
                  isDense: true,
                  border: const OutlineInputBorder(),
                ),
              ),
            ),
            if (ff != null) ...[
              const SizedBox(width: 8),
              DropdownButton<String>(
                value: _filter,
                underline: const SizedBox.shrink(),
                onChanged: (v) {
                  setState(() => _filter = v ?? _all);
                  _load(reset: true);
                },
                items: [
                  DropdownMenuItem(value: _all, child: Text('All ${(ff.pluralLabel ?? ff.label).toLowerCase()}')),
                  for (final c in ff.choices) DropdownMenuItem(value: c, child: Text(humanize(c))),
                ],
              ),
            ],
          ]),
        ),
        if (_hasApproval)
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 4),
            child: SegmentedButton<String>(
              segments: const [
                ButtonSegment(value: _all, label: Text('All')),
                ButtonSegment(value: 'pending', label: Text('Pending')),
                ButtonSegment(value: 'approved', label: Text('Approved')),
                ButtonSegment(value: 'rejected', label: Text('Rejected')),
              ],
              selected: {_approval},
              showSelectedIcon: false,
              onSelectionChanged: (s) {
                setState(() => _approval = s.first);
                _load(reset: true);
              },
            ),
          ),
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 4),
          child: Row(children: [
            Text('${widget.title ?? r.plural} · $_total',
                style: Theme.of(context).textTheme.titleSmall),
            const Spacer(),
            if (_loading) const SizedBox(width: 16, height: 16, child: CircularProgressIndicator(strokeWidth: 2)),
          ]),
        ),
        if (_error.isNotEmpty)
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 16),
            child: McnAlert(_error, destructive: true),
          ),
        Expanded(
          child: RefreshIndicator(
            onRefresh: () => _load(reset: true),
            child: _rows.isEmpty && !_loading
                ? ListView(children: [
                    const SizedBox(height: 80),
                    Center(
                        child: Text(_search.isNotEmpty || _filter != _all
                            ? 'No ${r.plural.toLowerCase()} match your search'
                            : 'No ${r.plural.toLowerCase()} yet')),
                  ])
                : ListView.builder(
                    padding: const EdgeInsets.fromLTRB(12, 4, 12, 96),
                    itemCount: _rows.length + (_rows.length < _total ? 1 : 0),
                    itemBuilder: (context, i) {
                      if (i == _rows.length) {
                        return Padding(
                          padding: const EdgeInsets.all(12),
                          child: OutlinedButton(
                            onPressed: _loading
                                ? null
                                : () {
                                    _page += 1;
                                    _load();
                                  },
                            child: const Text('Load more'),
                          ),
                        );
                      }
                      final row = _rows[i];
                      final title = titleField != null ? mcnStr(row[titleField.name]) : '#${row['id']}';
                      final details = [
                        for (final f in visible)
                          if (f != titleField && f.type != 'choice' && displayText(f, row).isNotEmpty)
                            displayText(f, row),
                      ];
                      final badges = [
                        for (final f in visible)
                          if (f.type == 'choice' && row[f.name] != null)
                            McnBadge(row[f.name].toString(),
                                color: badgeColor(row[f.name].toString(), f.choices.indexOf(row[f.name].toString()))),
                        if (_hasApproval && row['approval_status'] != null)
                          McnBadge(row['approval_status'].toString()),
                      ];
                      return Card(
                        child: ListTile(
                          onTap: () => _open(row),
                          title: Text(title.isEmpty ? '#${row['id']}' : title),
                          subtitle: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                            if (details.isNotEmpty) Text(details.join(' · '), maxLines: 2, overflow: TextOverflow.ellipsis),
                            if (badges.isNotEmpty) ...[
                              const SizedBox(height: 6),
                              Wrap(spacing: 6, runSpacing: 4, children: badges),
                            ],
                          ]),
                          trailing: const Icon(Icons.chevron_right),
                        ),
                      );
                    },
                  ),
          ),
        ),
      ]),
    );
  }
}

/// Text for one field of a record (labels for refs, file names, Yes/No …).
String displayText(Field f, Map<String, dynamic> row) {
  final v = row[f.name];
  if (v == null || v == '') return '';
  switch (f.type) {
    case 'ref':
      return mcnStr(row['${f.name}_label'] ?? '#$v');
    case 'file':
      final file = row['${f.name}_file'];
      return file is Map ? mcnStr(file['name']) : '';
    case 'bool':
      return v == true ? '${f.label}: Yes' : '${f.label}: No';
    case 'int':
    case 'float':
    case 'number':
      return formatNumber(v);
    default:
      return mcnStr(v);
  }
}

// ── Record screen: view / create / edit / delete / approve ──────────────────

class RecordScreen extends StatefulWidget {
  const RecordScreen({super.key, required this.resource, this.row, this.approval = false});

  final Resource resource;
  final Map<String, dynamic>? row;
  final bool approval;

  @override
  State<RecordScreen> createState() => _RecordScreenState();
}

class _RecordScreenState extends State<RecordScreen> {
  final _values = <String, dynamic>{};
  final _controllers = <String, TextEditingController>{};
  Map<String, String> _fieldErrors = const {};
  String _error = '';
  bool _busy = false;

  Resource get r => widget.resource;
  bool get _editing => widget.row != null;

  @override
  void initState() {
    super.initState();
    for (final f in r.fields) {
      final v = widget.row?[f.name] ?? (widget.row == null ? f.defaultValue : null);
      _values[f.name] = f.type == 'password' ? '' : v;
      if (_isText(f)) _controllers[f.name] = TextEditingController(text: f.type == 'password' ? '' : mcnStr(v));
    }
  }

  @override
  void dispose() {
    for (final c in _controllers.values) {
      c.dispose();
    }
    super.dispose();
  }

  bool _isText(Field f) =>
      const ['str', 'string', 'text', 'int', 'float', 'number', 'password', 'any'].contains(f.type);

  bool _canRead(AuthState auth, Field f) =>
      f.readRoles.isEmpty || !auth.enabled || f.readRoles.contains(auth.role);

  bool _canWrite(AuthState auth, Field f) =>
      _canRead(auth, f) && (f.writeRoles.isEmpty || !auth.enabled || f.writeRoles.contains(auth.role));

  Future<void> _save(AuthState auth) async {
    setState(() {
      _busy = true;
      _error = '';
      _fieldErrors = const {};
    });
    final payload = <String, dynamic>{};
    for (final f in r.fields) {
      if (!_canWrite(auth, f)) continue;
      payload[f.name] = _controllers[f.name]?.text ?? _values[f.name];
    }
    try {
      if (_editing) {
        await api.post(r.endpoints['update']!, {'id': widget.row!['id'], ...payload});
      } else {
        await api.post(r.endpoints['create']!, payload);
      }
      if (mounted) Navigator.of(context).pop(true);
    } on ApiError catch (e) {
      setState(() {
        _error = e.message;
        _fieldErrors = e.fieldErrors;
      });
    } catch (e) {
      setState(() => _error = e.toString());
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _delete() async {
    final name = r.labelField != null ? mcnStr(widget.row![r.labelField!.name]) : '#${widget.row!['id']}';
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text('Delete ${r.label.toLowerCase()}?'),
        content: Text('“$name” will be permanently deleted.'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
          FilledButton(
            style: FilledButton.styleFrom(backgroundColor: Theme.of(ctx).colorScheme.error),
            onPressed: () => Navigator.pop(ctx, true),
            child: const Text('Delete'),
          ),
        ],
      ),
    );
    if (ok != true) return;
    try {
      await api.post(r.endpoints['delete']!, {'id': widget.row!['id']});
      if (mounted) Navigator.of(context).pop(true);
    } catch (e) {
      setState(() => _error = e.toString());
    }
  }

  Future<void> _decide(String decision) async {
    final note = TextEditingController();
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text('${decision == 'approve' ? 'Approve' : 'Reject'} ${r.label.toLowerCase()}?'),
        content: TextField(
          controller: note,
          maxLines: 3,
          decoration: InputDecoration(
              labelText: decision == 'reject' ? 'Note (tell them why)' : 'Note (optional)',
              border: const OutlineInputBorder()),
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
          FilledButton(onPressed: () => Navigator.pop(ctx, true),
              child: Text(decision == 'approve' ? 'Approve' : 'Reject')),
        ],
      ),
    );
    if (ok != true) return;
    try {
      await api.post(r.endpoints[decision]!, {'id': widget.row!['id'], 'note': note.text});
      if (mounted) Navigator.of(context).pop(true);
    } catch (e) {
      setState(() => _error = e.toString());
    }
  }

  @override
  Widget build(BuildContext context) {
    final auth = AuthScope.of(context);
    final canSave = auth.can(r.endpoints[_editing ? 'update' : 'create']!);
    final canDelete = _editing && auth.can(r.endpoints['delete']!);
    final pending = widget.approval && widget.row?['approval_status'] == 'pending';
    final canApprove = pending && auth.can(r.endpoints['approve'] ?? '');
    final fields = r.fields.where((f) => _canRead(auth, f)).toList();

    return Scaffold(
      appBar: AppBar(
        title: Text(_editing ? (canSave ? 'Edit ${r.label.toLowerCase()}' : r.label) : 'New ${r.label.toLowerCase()}'),
        actions: [
          if (canDelete)
            IconButton(tooltip: 'Delete', icon: const Icon(Icons.delete_outline), onPressed: _delete),
        ],
      ),
      body: ListView(padding: const EdgeInsets.all(16), children: [
        if (widget.approval && widget.row?['approval_status'] != null)
          Padding(
            padding: const EdgeInsets.only(bottom: 12),
            child: Row(children: [
              McnBadge(widget.row!['approval_status'].toString()),
              const SizedBox(width: 8),
              Expanded(
                child: Text([
                  if (widget.row!['approval_by'] != null) 'by ${widget.row!['approval_by']}',
                  if (widget.row!['approval_note'] != null) '“${widget.row!['approval_note']}”',
                ].join(' · '), style: Theme.of(context).textTheme.bodySmall),
              ),
            ]),
          ),
        for (final f in fields) ...[
          _input(f, enabled: canSave && _canWrite(auth, f)),
          const SizedBox(height: 14),
        ],
        if (_error.isNotEmpty && _fieldErrors.isEmpty) ...[
          McnAlert(_error, destructive: true),
          const SizedBox(height: 12),
        ],
        if (canApprove)
          Row(children: [
            Expanded(
              child: OutlinedButton.icon(
                  onPressed: () => _decide('reject'), icon: const Icon(Icons.close), label: const Text('Reject')),
            ),
            const SizedBox(width: 12),
            Expanded(
              child: FilledButton.icon(
                  onPressed: () => _decide('approve'), icon: const Icon(Icons.check), label: const Text('Approve')),
            ),
          ]),
        if (canSave) ...[
          const SizedBox(height: 12),
          FilledButton(
            onPressed: _busy ? null : () => _save(auth),
            child: Text(_editing ? 'Save changes' : 'Create ${r.label.toLowerCase()}'),
          ),
        ],
      ]),
    );
  }

  Widget _input(Field f, {required bool enabled}) {
    final label = '${f.label}${f.required && !(_editing && f.type == 'password') ? ' *' : ''}';
    final error = _fieldErrors[f.name] == null ? null : '${f.label} ${_fieldErrors[f.name]}';
    final deco = InputDecoration(labelText: label, errorText: error, border: const OutlineInputBorder());
    switch (f.type) {
      case 'bool':
        return SwitchListTile(
          contentPadding: EdgeInsets.zero,
          title: Text(f.label),
          subtitle: error == null ? null : Text(error, style: TextStyle(color: Theme.of(context).colorScheme.error)),
          value: _values[f.name] == true,
          onChanged: enabled ? (v) => setState(() => _values[f.name] = v) : null,
        );
      case 'choice':
        return DropdownButtonFormField<String>(
          initialValue: f.choices.contains(_values[f.name]) ? _values[f.name] as String : null,
          decoration: deco,
          items: [
            if (!f.required) const DropdownMenuItem<String>(value: null, child: Text('—')),
            for (final c in f.choices) DropdownMenuItem(value: c, child: Text(humanize(c))),
          ],
          onChanged: enabled ? (v) => setState(() => _values[f.name] = v) : null,
        );
      case 'ref':
        return RefDropdown(field: f, value: _values[f.name], decoration: deco, enabled: enabled,
            onChanged: (v) => setState(() => _values[f.name] = v));
      case 'date':
      case 'datetime':
        final text = mcnStr(_values[f.name]);
        return InkWell(
          onTap: !enabled
              ? null
              : () async {
                  final initial = DateTime.tryParse(text) ?? DateTime.now();
                  final day = await showDatePicker(
                      context: context, initialDate: initial,
                      firstDate: DateTime(1900), lastDate: DateTime(2200));
                  if (day == null) return;
                  var value = day.toIso8601String().substring(0, 10);
                  if (f.type == 'datetime' && mounted) {
                    final t = await showTimePicker(context: context, initialTime: TimeOfDay.fromDateTime(initial));
                    if (t != null) {
                      value = '${value}T${t.hour.toString().padLeft(2, '0')}:${t.minute.toString().padLeft(2, '0')}';
                    }
                  }
                  setState(() => _values[f.name] = value);
                },
          child: InputDecorator(
            decoration: deco.copyWith(suffixIcon: const Icon(Icons.calendar_today_outlined)),
            child: Text(text.isEmpty ? '—' : text.replaceFirst('T', ' ')),
          ),
        );
      case 'file':
        return FileField(field: f, row: widget.row, decoration: deco, enabled: enabled,
            onChanged: (id) => setState(() => _values[f.name] = id));
      case 'text':
        return TextField(controller: _controllers[f.name], enabled: enabled, maxLines: 4, decoration: deco);
      case 'int':
      case 'float':
      case 'number':
        return TextField(
          controller: _controllers[f.name],
          enabled: enabled,
          keyboardType: TextInputType.numberWithOptions(decimal: f.type != 'int', signed: true),
          decoration: deco,
        );
      case 'password':
        return TextField(
          controller: _controllers[f.name],
          enabled: enabled,
          obscureText: true,
          decoration: deco.copyWith(
              hintText: _editing ? 'Leave blank to keep the current password' : 'At least 8 characters'),
        );
      default:
        return TextField(controller: _controllers[f.name], enabled: enabled, decoration: deco);
    }
  }
}

/// Dropdown of records from a linked resource (`company: ref Company`).
class RefDropdown extends StatefulWidget {
  const RefDropdown({super.key, required this.field, required this.value, required this.decoration,
      required this.enabled, required this.onChanged});

  final Field field;
  final dynamic value;
  final InputDecoration decoration;
  final bool enabled;
  final ValueChanged<dynamic> onChanged;

  @override
  State<RefDropdown> createState() => _RefDropdownState();
}

class _RefDropdownState extends State<RefDropdown> {
  List<Map<String, dynamic>> _options = const [];
  String _error = '';

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    final ref = widget.field.ref!;
    final query = {'page_size': '200', if (ref.labelField != null) 'sort': ref.labelField!};
    try {
      final d = await api.get(ref.list, query);
      if (!mounted) return;
      setState(() => _options = [
            for (final i in (d['items'] as List? ?? const [])) Map<String, dynamic>.from(i as Map)
          ]);
    } catch (e) {
      if (mounted) setState(() => _error = e.toString());
    }
  }

  @override
  Widget build(BuildContext context) {
    final ref = widget.field.ref!;
    final current = widget.value == null || widget.value == '' ? null : int.tryParse(widget.value.toString());
    final ids = _options.map((o) => o['id']).toSet();
    return DropdownButtonFormField<int>(
      initialValue: ids.contains(current) ? current : null,
      isExpanded: true,
      decoration: widget.decoration.copyWith(errorText: widget.decoration.errorText ?? (_error.isEmpty ? null : _error)),
      hint: Text('Select ${ref.label.toLowerCase()}'),
      items: [
        if (!widget.field.required) const DropdownMenuItem<int>(value: null, child: Text('—')),
        for (final o in _options)
          DropdownMenuItem<int>(
            value: (o['id'] as num).toInt(),
            child: Text(ref.labelField != null && o[ref.labelField] != null
                ? o[ref.labelField].toString()
                : '#${o['id']}'),
          ),
      ],
      onChanged: widget.enabled ? (v) => widget.onChanged(v) : null,
    );
  }
}

/// Upload a file to the backend (`file` fields); stores the file id.
class FileField extends StatefulWidget {
  const FileField({super.key, required this.field, required this.row, required this.decoration,
      required this.enabled, required this.onChanged});

  final Field field;
  final Map<String, dynamic>? row;
  final InputDecoration decoration;
  final bool enabled;
  final ValueChanged<dynamic> onChanged;

  @override
  State<FileField> createState() => _FileFieldState();
}

class _FileFieldState extends State<FileField> {
  Map<String, dynamic>? _file;
  bool _busy = false;
  String _error = '';

  @override
  void initState() {
    super.initState();
    final f = widget.row?['${widget.field.name}_file'];
    if (f is Map) _file = Map<String, dynamic>.from(f);
  }

  Future<void> _pick() async {
    final PlatformFile? file = await FilePicker.pickFile();   // file_picker 13+
    if (file == null) return;
    setState(() {
      _busy = true;
      _error = '';
    });
    try {
      final bytes = await file.readAsBytes();
      final saved = await api.post('/upload', {'name': file.name, 'data': base64Encode(bytes)});
      setState(() => _file = Map<String, dynamic>.from(saved as Map));
      widget.onChanged(saved['id'].toString());
    } catch (e) {
      setState(() => _error = e.toString());
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return InputDecorator(
      decoration: widget.decoration.copyWith(errorText: widget.decoration.errorText ?? (_error.isEmpty ? null : _error)),
      child: Row(children: [
        Expanded(
          child: _file == null
              ? const Text('No file')
              : InkWell(
                  onTap: () => launchUrl(Uri.parse(api.url(_file!['url'].toString())),
                      mode: LaunchMode.externalApplication),
                  child: Row(children: [
                    const Icon(Icons.attach_file, size: 18),
                    Flexible(child: Text(_file!['name'].toString(), overflow: TextOverflow.ellipsis)),
                  ]),
                ),
        ),
        if (widget.enabled)
          TextButton.icon(
            onPressed: _busy ? null : _pick,
            icon: _busy
                ? const SizedBox(width: 16, height: 16, child: CircularProgressIndicator(strokeWidth: 2))
                : const Icon(Icons.upload_file),
            label: Text(_file == null ? 'Upload' : 'Replace'),
          ),
      ]),
    );
  }
}
